1	package netdiag
2	
3	import (
4		"fmt"
5		"net"
6		"net/netip"
7		"strconv"
8		"time"
9	
10		"github.com/anthnel/devdesk/internal/netcheck"
11		"github.com/anthnel/devdesk/internal/nettrace"
12	)
13	
14	// pathStepKind says which kind of row a pathStep is.
15	type pathStepKind int
16	
17	// The kinds of row, in the order the column shows them.
18	const (
19		stepSource pathStepKind = iota
20		stepInterface
21		stepGateway
22		stepHop
23	)
24	
25	// pathRoute is the way out of this machine for the traced address.
26	type pathRoute struct {
27		Known     bool // false: the lookup failed; interface and gateway are undetermined
28		Interface string
29		Source    netip.Addr // invalid: the stack did not say
30		Gateway   netip.Addr // invalid: directly connected
31	}
32	
33	// pathStep is one row of the Path column.
34	type pathStep struct {
35		Kind  pathStepKind
36		Route pathRoute    // stepInterface, stepGateway
37		Hop   nettrace.Hop // stepHop
38	}
39	
40	const (
41		sourceLabel       = "this machine"
42		routeUndetermined = "undetermined"
43		gatewayDirect     = "directly connected"
44	)
45	
46	// newPathRoute converts a route lookup into a pathRoute. A failed lookup
47	// discards whatever the hop holds. Addresses are unmapped to IPv4 when they can be.
48	func newPathRoute(hop netcheck.RouteHop, err error) pathRoute {
49		if err != nil {
50			return pathRoute{}
51		}
52		return pathRoute{
53			Known:     true,
54			Interface: hop.Interface,
55			Source:    addrFromIP(hop.Source),
56			Gateway:   addrFromIP(hop.Gateway),
57		}
58	}
59	
60	// addrFromIP returns ip as an unmapped netip.Addr, or the zero Addr for a nil or invalid ip.
61	func addrFromIP(ip net.IP) netip.Addr {
62		addr, ok := netip.AddrFromSlice(ip)
63		if !ok {
64			return netip.Addr{}
65		}
66		return addr.Unmap()
67	}
68	
69	// pathSteps returns the rows of the Path column: the source, then the
70	// interface and gateway when route is not nil, then the hops as selected by
71	// visiblePathHops. It returns nil while neither a route nor a hop exists.
72	// Neither input is modified.
73	func pathSteps(route *pathRoute, hops []nettrace.Hop) []pathStep {
74		if route == nil && len(hops) == 0 {
75			return nil
76		}
77		steps := []pathStep{{Kind: stepSource}}
78		if route != nil {
79			steps = append(steps,
80				pathStep{Kind: stepInterface, Route: *route},
81				pathStep{Kind: stepGateway, Route: *route},
82			)
83		}
84		for _, h := range visiblePathHops(hops) {
85			steps = append(steps, pathStep{Kind: stepHop, Hop: h})
86		}
87		return steps
88	}
89	
90	// hopCell is the TTL of a hop row; empty for the local rows.
91	func (s pathStep) hopCell() string {
92		if s.Kind != stepHop {
93			return ""
94		}
95		return strconv.Itoa(s.Hop.TTL)
96	}
97	
98	// stepCell names the kind of row.
99	func (s pathStep) stepCell() string {
100		switch s.Kind {
101		case stepSource:
102			return "source"
103		case stepInterface:
104			return "interface"
105		case stepGateway:
106			return "gateway"
107		}
108		return s.Hop.Kind.String()
109	}
110	
111	// addressCell is the main text of the row.
112	func (s pathStep) addressCell() string {
113		switch s.Kind {
114		case stepSource:
115			return sourceLabel
116		case stepInterface:
117			return s.Route.interfaceText()
118		case stepGateway:
119			return s.Route.gatewayText()
120		}
121		return addrOrDash(s.Hop.Addr)
122	}
123	
124	// rttCell is the round-trip time of a hop that answered; "-" otherwise.
125	func (s pathStep) rttCell() string {
126		if s.Kind != stepHop {
127			return ""
128		}
129		if s.Hop.RTT <= 0 {
130			return "-"
131		}
132		return fmt.Sprintf("%.1f ms", float64(s.Hop.RTT)/float64(time.Millisecond))
133	}
134	
135	// interfaceText is the interface name, followed by the source address when known.
136	func (r pathRoute) interfaceText() string {
137		if !r.Known || (r.Interface == "" && !r.Source.IsValid()) {
138			return routeUndetermined
139		}
140		name := r.Interface
141		if name == "" {
142			name = "unnamed"
143		}
144		if !r.Source.IsValid() {
145			return name
146		}
147		return name + " (" + r.Source.String() + ")"
148	}
149	
150	// gatewayText is the gateway address, or says the destination is directly connected.
151	func (r pathRoute) gatewayText() string {
152		switch {
153		case !r.Known:
154			return routeUndetermined
155		case !r.Gateway.IsValid() || r.Gateway.IsUnspecified():
156			return gatewayDirect
157		}
158		return r.Gateway.String()
159	}
160	
161	// addrOrDash formats an address, or "-" when there is none.
162	func addrOrDash(a netip.Addr) string {
163		if !a.IsValid() {
164			return "-"
165		}
166		return a.String()
167	}
168

1	package netdiag
2	
3	import (
4		"context"
5		"fmt"
6		"log"
7		"net"
8		"net/netip"
9		"time"
10	
11		tea "charm.land/bubbletea/v2"
12	
13		"github.com/anthnel/devdesk/internal/netcheck"
14		"github.com/anthnel/devdesk/internal/nettrace"
15	)
16	
17	// pathChanCap holds a whole trace: every hop (at most MaxHopsLimit), the
18	// resolved message and the done message. The producer therefore never waits
19	// for a reader.
20	const pathChanCap = nettrace.MaxHopsLimit + 2
21	
22	// pathEngine is the seam between the path tab and the network: tests replace
23	// it with a fake.
24	type pathEngine struct {
25		supported func() error
26		resolve   func(ctx context.Context, host string) ([]netip.Addr, error)
27		route     func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error)
28		trace     func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)
29	}
30	
31	// systemPathEngine returns the engine backed by the real resolver and sockets.
32	func systemPathEngine() pathEngine {
33		env := netcheck.SystemEnv(netcheck.DefaultSettings())
34		return pathEngine{
35			supported: nettrace.Supported,
36			resolve: func(ctx context.Context, host string) ([]netip.Addr, error) {
37				return net.DefaultResolver.LookupNetIP(ctx, "ip4", host)
38			},
39			route: func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error) {
40				return env.Route(ctx, net.IP(a.AsSlice()))
41			},
42			trace: nettrace.TraceEach,
43		}
44	}
45	
46	// pathResolvedMsg reports the address the target resolved to.
47	type pathResolvedMsg struct {
48		gen      int
49		addr     netip.Addr
50		route    netcheck.RouteHop
51		routeErr error
52	}
53	
54	// pathHopMsg carries one hop as the engine reports it.
55	type pathHopMsg struct {
56		gen int
57		hop nettrace.Hop
58	}
59	
60	// pathDoneMsg ends a run: a result, or an error when no trace happened.
61	type pathDoneMsg struct {
62		gen    int
63		result nettrace.Result
64		err    error
65	}
66	
67	// producePath resolves the target, traces it and sends the messages to out,
68	// then closes out. It runs inside a Cmd and touches no model (Rule 110).
69	// out must have room for pathChanCap messages: sends never block, so a view
70	// that stops reading after canceling leaks nothing.
71	func producePath(ctx context.Context, gen int, tg pathTarget, resolveTimeout time.Duration, e pathEngine, out chan tea.Msg) {
72		defer close(out)
73		send := func(m tea.Msg) {
74			select {
75			case out <- m:
76			default:
77			}
78		}
79		// sendDone must never be lost: when the channel is full the oldest message
80		// is dropped to make room. The producer is the only sender, so one drop
81		// frees a slot for good.
82		sendDone := func(m tea.Msg) {
83			for range 2 {
84				select {
85				case out <- m:
86					return
87				default:
88				}
89				select {
90				case <-out:
91				default:
92				}
93			}
94		}
95	
96		addr, err := resolvePathTarget(ctx, tg.Host, resolveTimeout, e)
97		if err != nil {
98			if ctx.Err() == nil { // esc during the resolution is not an error
99				log.Printf("ERROR [netdiag/path] resolve %s: %v", tg.Host, err)
100			}
101			sendDone(pathDoneMsg{gen: gen, err: err})
102			return
103		}
104		// The route is asked for the address actually traced. A failure is not
105		// fatal and is never shown: the trace goes on without the route column.
106		route, routeErr := e.route(ctx, addr)
107		if routeErr != nil && ctx.Err() == nil {
108			log.Printf("ERROR [netdiag/path] route %s: %v", tg.Host, routeErr)
109		}
110		send(pathResolvedMsg{gen: gen, addr: addr, route: route, routeErr: routeErr})
111	
112		res, err := e.trace(ctx, addr, nettrace.Options{}, func(h nettrace.Hop) {
113			send(pathHopMsg{gen: gen, hop: h})
114		})
115		if err != nil {
116			log.Printf("ERROR [netdiag/path] trace %s: %v", tg.Host, err)
117		}
118		sendDone(pathDoneMsg{gen: gen, result: res, err: err})
119	}
120	
121	// resolvePathTarget returns the IPv4 address to trace: a literal is used as
122	// is, a name is resolved under its own timeout.
123	func resolvePathTarget(ctx context.Context, host string, timeout time.Duration, e pathEngine) (netip.Addr, error) {
124		if a, err := netip.ParseAddr(host); err == nil && a.Is4() {
125			return a, nil
126		}
127		rctx, cancel := context.WithTimeout(ctx, timeout)
128		defer cancel()
129		addrs, err := e.resolve(rctx, host)
130		if err != nil {
131			return netip.Addr{}, fmt.Errorf("%w: %w", errPathResolve, err)
132		}
133		if len(addrs) == 0 {
134			return netip.Addr{}, errPathNoIPv4
135		}
136		return addrs[0], nil
137	}
138	
139	// waitForPathMsg returns a Cmd that yields the next message of in, or nil
140	// once in is closed. The view re-arms it after every message.
141	func waitForPathMsg(in <-chan tea.Msg) tea.Cmd {
142		return func() tea.Msg {
143			m, ok := <-in
144			if !ok {
145				return nil
146			}
147			return m
148		}
149	}
