1	package netdiag
2	
3	import (
4		"fmt"
5	
6		"charm.land/lipgloss/v2"
7	
8		"github.com/anthnel/devdesk/internal/nettrace"
9		"github.com/anthnel/devdesk/internal/ui/components"
10		"github.com/anthnel/devdesk/internal/ui/datatable"
11		"github.com/anthnel/devdesk/internal/ui/shortcut"
12		"github.com/anthnel/devdesk/internal/ui/theme"
13	)
14	
15	// pathBarLabel prefixes the target field in the bar.
16	const pathBarLabel = "Target › "
17	
18	// pathColumns describes the Path column. Plain text in Cell, colour in Style
19	// (Rule 122). A silent hop is dim, never red: it is not a failure.
20	func pathColumns() []datatable.Column[pathStep] {
21		hop := datatable.Column[pathStep]{
22			Title: "Hop", Sizing: datatable.SizingFixed, MinWidth: 3,
23			Cell: pathStep.hopCell,
24		}
25		step := datatable.Column[pathStep]{
26			Title: "Step", Sizing: datatable.SizingFixed, MinWidth: 11,
27			Cell:  pathStep.stepCell,
28			Style: pathStepStyle,
29		}
30		address := datatable.Column[pathStep]{
31			Title: "Address", Sizing: datatable.SizingContent, MinWidth: 15, Flex: 1,
32			Cell:  pathStep.addressCell,
33			Style: pathAddressStyle,
34		}
35		rtt := datatable.Column[pathStep]{
36			Title: "RTT", Sizing: datatable.SizingFixed, MinWidth: 9,
37			Cell:  pathStep.rttCell,
38			Style: pathRTTStyle,
39		}
40		return []datatable.Column[pathStep]{hop, step, address, rtt}
41	}
42	
43	func pathStepStyle(s pathStep) lipgloss.Style {
44		if s.Kind != stepHop {
45			return lipgloss.Style{}
46		}
47		switch s.Hop.Kind {
48		case nettrace.HopSilent, nettrace.HopUnresolved:
49			return theme.DimStyle
50		case nettrace.HopError:
51			return theme.SeverityTextStyle("MEDIUM")
52		}
53		return lipgloss.Style{}
54	}
55	
56	func pathAddressStyle(s pathStep) lipgloss.Style {
57		switch s.Kind {
58		case stepHop:
59			if !s.Hop.Addr.IsValid() {
60				return theme.DimStyle
61			}
62		case stepInterface, stepGateway:
63			if c := s.addressCell(); c == routeUndetermined || c == gatewayDirect {
64				return theme.DimStyle
65			}
66		}
67		return lipgloss.Style{}
68	}
69	
70	func pathRTTStyle(s pathStep) lipgloss.Style {
71		if s.Kind == stepHop && s.Hop.RTT <= 0 {
72			return theme.DimStyle
73		}
74		return lipgloss.Style{}
75	}
76	
77	// view renders the table; the body is never replaced (Rule 139).
78	func (pm *PathModel) view() string { return pm.table.View() }
79	
80	// barView is the target field in its frame, two lines in every state.
81	func (pm *PathModel) barView(width int) string {
82		return components.BarFrame(width, theme.KeyStyle.Render(pathBarLabel)+pm.input.View())
83	}
84	
85	// statusLine is derived on every frame (Rule 128).
86	func (pm *PathModel) statusLine() components.Status {
87		if pm.errText != "" {
88			return components.Status{Text: pm.errText, Level: components.LevelError}
89		}
90		if pm.state != pathRunning {
91			return components.Status{}
92		}
93		host := pm.target.Host
94		n := pm.hopCount()
95		if !pm.addr.IsValid() && n == 0 {
96			return components.Status{Text: "Resolving " + host + "...", Activity: true}
97		}
98		where := host
99		if pm.addr.IsValid() && pm.addr.String() != host {
100			where += " (" + pm.addr.String() + ")"
101		}
102		noun := "hops"
103		if n == 1 {
104			noun = "hop"
105		}
106		return components.Status{
107			Text:     fmt.Sprintf("Tracing %s — %d %s answered", where, n, noun),
108			Activity: true,
109		}
110	}
111	
112	// headerInfo lists the target and, once a run ended, how it ended.
113	func (pm *PathModel) headerInfo() []shortcut.HeaderInfo {
114		var out []shortcut.HeaderInfo
115		if pm.target.Host != "" {
116			value := pm.target.String()
117			if pm.addr.IsValid() && pm.addr.String() != pm.target.Host {
118				value += " (" + pm.addr.String() + ")"
119			}
120			out = append(out, shortcut.HeaderInfo{Key: "Target", Value: value, Style: theme.HeaderValueStyle})
121		}
122		if pm.result != nil {
123			out = append(out, shortcut.HeaderInfo{Key: "Path", Value: pathOutcomeLabel(*pm.result), Style: theme.HeaderValueStyle})
124		}
125		return out
126	}
127	
128	// shortcuts: the running mode replaces the list, the other states grey out
129	// (Rule 130).
130	func (pm *PathModel) shortcuts() shortcut.Shortcuts {
131		off := !pm.launchable().Enabled()
132		switch pm.state {
133		case pathRunning:
134			return shortcut.Shortcuts{{Key: "esc", Description: "Cancel the trace"}}
135		case pathDone:
136			return shortcut.Shortcuts{
137				{Key: "tab", Description: "Switch tab"},
138				{Key: "enter", Description: "Trace again", Disabled: off},
139				{Key: "esc", Description: "Edit the target"},
140				{Key: "?", Description: "Help"},
141			}
142		}
143		return shortcut.Shortcuts{
144			{Key: "tab", Description: "Switch tab"},
145			{Key: "enter", Description: "Trace the path", Disabled: off},
146		}
147	}
