// Package engine names the container engine DevDesk drives — docker or podman —
// and carries everything about it that is not the same between the two.
//
// It exists as its own package rather than as a field of internal/docker
// because internal/scan needs the same answer and does not import
// internal/docker. That is the internal/forge arrangement read one level down:
// the thing every caller shares does not live inside one of its callers.
//
// What a Shape carries is what measurement, not taste, put there (§3.67):
//
//   - the binary, which is the cheap part — internal/docker already funnels
//     every invocation through one runner;
//   - the credential helper prefix and the auth file, because that file is read
//     *and written* directly rather than through the CLI;
//   - the host socket, which is the one path that breaks rather than moves:
//     rootless podman has no /var/run/docker.sock, and its own socket exists
//     only while `podman system service` runs;
//   - the output templates, which are the silent risk. See Templates.
//
// Nothing here sniffs. A shape is declared, the way a forge's is and the way a
// registry's `provider` is (§3.8): a thing is treated as what it says it is.
package engine

import (
	"fmt"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
)

// Shape is one container engine: what to run, where it keeps its credentials,
// and how to ask it for machine-readable output.
type Shape struct {
	// Name identifies the engine for a config discriminator, a log line, and
	// the word the views show — "docker", "podman".
	Name string

	// Binary is what gets executed. It is the engine's own name for the two
	// declared shapes, and an explicit path when the configuration names one.
	Binary string

	// Templates are the --format strings for every output this application
	// parses.
	Templates Templates
}

// A Shape carries no resolved filesystem path, and that is deliberate: the
// credential file and the socket are looked up through AuthPaths(), AuthPath()
// and HostSocket() at the moment they are needed.
//
// Storing them on the struct was tried and reverted. The shape is built once,
// at package initialisation, so a $HOME or $XDG_RUNTIME_DIR read there is
// frozen before anything else runs — and the socket is worse, since whether it
// exists is the entire question and it can appear (`podman system service`) or
// vanish while the application is up. A cached answer to "where is the file"
// is a cached answer to "does it exist", which is not a thing a shape can know
// once and for all.

// Templates holds one Go template per parsed output.
//
// They are a field of the shape rather than constants at the call sites for a
// reason a real podman went on to confirm: podman implements --format, but
// equality of the *fields* is guaranteed nowhere. A divergence does not
// always raise an error and produce a wrong row (the defect class this
// repository keeps cataloguing, D24, D25, D57) — three of the twelve outputs
// (Info, NetworkLS, SystemDF) name a field podman's template engine does not
// have at all, which fails the command outright instead. `podman info`
// exiting 125 on every poll is what host capacity looked like before this was
// measured.
//
// The other nine match dockerTemplates exactly against that same podman, so
// they stay unified rather than being forked speculatively. What this
// indirection buys is that a future divergence is one line here rather than a
// refactor. Do not collapse it back into constants (§3.67).
//
// The twelfth parsed output has no template and is not here: `system df -v` is
// a fixed-width table scraped by column offsets (internal/docker/images.go),
// because no --format exposes per-image unique size. See ParsesSystemDFVerbose.
type Templates struct {
	// PS lists containers: id, name, image, state, status, created, ports.
	PS string
	// PSState asks for nothing but the state column, to count containers.
	PSState string
	// Stats is the live resource sample, taken with --no-stream.
	Stats string
	// Info is the host's capacity: CPU count and total memory.
	Info string
	// ImageLS lists images: id, repository, tag, size, created.
	ImageLS string
	// ImageInspect reads the size and the registry digests of several images
	// in one call.
	ImageInspect string
	// ImageRepoDigests reads one image's registry digests as JSON.
	ImageRepoDigests string
	// ImageExposedPorts reads an image's EXPOSE declarations as JSON.
	ImageExposedPorts string
	// NetworkLS lists networks: id, name, driver, scope, created.
	NetworkLS string
	// VolumeLS lists volumes: name, driver, mountpoint.
	VolumeLS string
	// SystemDF is the disk report, one row per resource family.
	SystemDF string
	// Version is the client version, for the dashboard's tools table.
	Version string
}

// ParsesSystemDFVerbose reports whether `<engine> system df -v` prints the
// fixed-width "Images space usage:" table internal/docker scrapes for per-image
// unique size and container count.
//
// Only docker is known to. Under podman the columns are left empty rather than
// filled from offsets taken on a header that may not be the same one: a blank
// column reads as an absence, a value sliced out of the wrong column does not.
func (s Shape) ParsesSystemDFVerbose() bool { return s.Name == Docker }

// Engine names, shared with the configuration. They are duplicated in
// internal/config rather than imported from it so that config does not depend
// on this package; TestEveryConfiguredEngineHasAShape holds the two in step,
// the same arrangement the forge names have (§3.6).
const (
	// Docker is what `auto` resolves to when both engines are installed, and
	// what an unrecognised name falls back to.
	Docker = "docker"
	Podman = "podman"
)

// Auto asks for whichever engine is installed. It is the default, so that
// nobody who installed exactly one of the two is asked which one they meant —
// app.secret_backend's precedent (§3.9).
const Auto = "auto"

// dockerTemplates is the set every call in this application was written
// against. podmanTemplates is a copy, and stays a copy until the measurement
// described on Templates has been made.
var dockerTemplates = Templates{
	PS:                "{{.ID}}\t{{.Names}}\t{{.Image}}\t{{.State}}\t{{.Status}}\t{{.CreatedAt}}\t{{.Ports}}",
	PSState:           "{{.State}}",
	Stats:             "{{.ID}}\t{{.CPUPerc}}\t{{.MemUsage}}\t{{.MemPerc}}\t{{.NetIO}}\t{{.BlockIO}}",
	Info:              "{{.NCPU}}\t{{.MemTotal}}",
	ImageLS:           "{{.ID}}\t{{.Repository}}\t{{.Tag}}\t{{.Size}}\t{{.CreatedAt}}",
	ImageInspect:      "{{.ID}}\t{{.Size}}\t{{json .RepoDigests}}",
	ImageRepoDigests:  "{{json .RepoDigests}}",
	ImageExposedPorts: "{{json .Config.ExposedPorts}}",
	NetworkLS:         "{{.ID}}\t{{.Name}}\t{{.Driver}}\t{{.Scope}}\t{{.CreatedAt}}",
	VolumeLS:          "{{.Name}}\t{{.Driver}}\t{{.Mountpoint}}",
	SystemDF:          "{{.Type}}\t{{.TotalCount}}\t{{.Size}}\t{{.Reclaimable}}",
	Version:           "{{.Client.Version}}",
}

// podmanTemplates diverges from dockerTemplates on the three outputs measured
// against a real `podman system service` (§3.67): Info, NetworkLS and
// SystemDF each name a docker-only struct field, and podman's template
// engine — unlike its JSON output, which does carry the docker-shaped field
// under a different name or nested — fails the whole command rather than
// leaving the field blank. `podman info` exits 125 outright, which is what
// broke host capacity reporting for every podman user; the other two return
// no rows.
//
//   - Info: podman nests CPU count and memory under .Host, not at the root.
//     This is also the field `dk setup`'s container-engine question caught,
//     via `docker.FetchCapacity` erroring outright on a genuinely running
//     podman instead of reporting it unreachable for some other reason.
//   - NetworkLS: podman networks carry no scope (docker's Scope column is a
//     swarm concept), and podman's field is called Created, not CreatedAt.
//     The Scope segment is left empty rather than guessed at "local" — the
//     same call HostSocket makes about reporting an absence as a fact.
//   - SystemDF: podman's template-formatted row exposes Total, not the
//     TotalCount its own `--format json` uses for the same count.
//
// The other nine outputs were checked against the same podman and matched
// dockerTemplates exactly, so they are not copied here.
var podmanTemplates = func() Templates {
	t := dockerTemplates
	t.Info = "{{.Host.CPUs}}\t{{.Host.MemTotal}}"
	t.NetworkLS = "{{.ID}}\t{{.Name}}\t{{.Driver}}\t\t{{.Created}}"
	t.SystemDF = "{{.Type}}\t{{.Total}}\t{{.Size}}\t{{.Reclaimable}}"
	return t
}()

// current is the resolved engine. It starts as docker so that every caller has
// a usable answer before the router has read a configuration — which is what
// the application did before this package existed, and what a test that never
// resolves anything should keep seeing.
var (
	currentMu sync.RWMutex
	current   = shapeFor(Docker, Docker)
)

// Current returns the engine in use.
func Current() Shape {
	currentMu.RLock()
	defer currentMu.RUnlock()
	return current
}

// SetCurrent installs the resolved engine. The router calls it once at startup
// and once per context switch, from Update — never from a Cmd (Rule 110).
func SetCurrent(s Shape) {
	currentMu.Lock()
	defer currentMu.Unlock()
	current = s
}

// Names lists the engines a shape is declared for, in the order the
// configuration view cycles them.
func Names() []string { return []string{Docker, Podman} }

// Resolve turns an app.container_engine value into the engine to drive.
//
// The four cases:
//
//	""/"auto"  docker if it is on PATH, else podman, else an error naming both
//	"docker"   pinned; absent is an error
//	"podman"   pinned; absent is an error
//	anything   taken as a path to a binary
//
// A pinned engine that is not installed is an error rather than a fall back to
// the other one. That is credentials.Select's rule (§3.9), and for the same
// reason: someone who asked for podman should not silently get docker, because
// the two do not hold the same containers.
func Resolve(preference string) (Shape, error) {
	switch preference {
	case "", Auto:
		for _, name := range Names() {
			if _, err := exec.LookPath(name); err == nil {
				return shapeFor(name, name), nil
			}
		}
		return Shape{}, fmt.Errorf("no container engine found: neither %s nor %s is on PATH", Docker, Podman)

	case Docker, Podman:
		if _, err := exec.LookPath(preference); err != nil {
			return Shape{}, fmt.Errorf("%s not found: %w", preference, err)
		}
		return shapeFor(preference, preference), nil
	}

	// Anything else is a path. The engine it belongs to is read from the file
	// name — the one place this package guesses, and it guesses about a value
	// the user typed rather than about the world. Getting it wrong costs the
	// auth file location, not the invocation.
	path := preference
	if _, err := exec.LookPath(path); err != nil {
		return Shape{}, fmt.Errorf("container engine %q not found: %w", path, err)
	}
	return shapeFor(engineOfPath(path), path), nil
}

// engineOfPath reads an engine name out of a configured path. Everything that
// is not recognisably podman is treated as docker, which is what an unknown
// docker-compatible CLI (nerdctl, a wrapper script) behaves like.
func engineOfPath(path string) string {
	base := strings.ToLower(filepath.Base(path))
	base = strings.TrimSuffix(base, ".exe")
	if strings.HasPrefix(base, Podman) {
		return Podman
	}
	return Docker
}

// shapeFor builds the shape for one engine, running the given binary.
func shapeFor(name, binary string) Shape {
	if name == Podman {
		return Shape{
			Name:      Podman,
			Binary:    binary,
			Templates: podmanTemplates,
		}
	}
	return Shape{
		Name:      Docker,
		Binary:    binary,
		Templates: dockerTemplates,
	}
}

// ShapeFor returns the declared shape for an engine name, running that name as
// its binary. It answers the configuration view, which needs the shapes before
// anything has been resolved — internal/forge's reason for holding its shapes
// in a table rather than on its backends.
func ShapeFor(name string) Shape { return shapeFor(name, name) }

package components

import (
	"strings"

	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ChoiceModal asks "which of these actions, or none".
//
// ConfirmModal poses a closed question and OptionConfirmModal a closed
// question paired with a variant; neither one can offer two distinct
// actions. §3.26 needs this for `K`: stop and restart are two gestures, not
// one gesture and its modifier — a restart is a stop followed by a start,
// and presenting the second as a checkbox of the first would turn an
// exclusive choice into a toggle (Rule 132).
//
// Cancel is the default choice, like "No" elsewhere (Rule 104): both of
// these actions cut ongoing connections.
type ChoiceModal struct {
	title   string
	message string
	choices []string
	// focused indexes choices, and equals len(choices) on Cancel — which is
	// therefore always the last button, without needing to be in the list.
	focused int
	width   int
	height  int
}

// NewChoiceModal creates a modal with N actions plus Cancel, focused on Cancel.
func NewChoiceModal(title, message string, choices ...string) *ChoiceModal {
	return &ChoiceModal{
		title:   title,
		message: message,
		choices: choices,
		focused: len(choices), // Cancel
	}
}

// ChoiceModalPickedMsg is sent when the user picks an action.
// Index and Label refer to the same thing: the index for routing, the label
// for logging without having to re-translate it.
type ChoiceModalPickedMsg struct {
	Index int
	Label string
}

// ChoiceModalCancelledMsg is sent when the user gives up.
type ChoiceModalCancelledMsg struct{}

// Update updates the modal.
func (m *ChoiceModal) Update(msg tea.Msg) (*ChoiceModal, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height

	case tea.KeyPressMsg:
		switch msg.String() {
		// ←/→ between buttons (Rule 135 — Tab is reserved for tabs). The
		// traversal is bounded rather than cyclic: Cancel must stay the end
		// of the run, otherwise one extra press would loop back onto an action.
		case "left":
			m.focused = max(m.focused-1, 0)
			return m, nil

		case "right":
			m.focused = min(m.focused+1, len(m.choices))
			return m, nil

		case "enter":
			return m, m.pick()

		case "esc":
			return m, cancelChoice
		}
	}

	return m, nil
}

// pick returns the command matching the focused button.
func (m *ChoiceModal) pick() tea.Cmd {
	if m.focused >= len(m.choices) {
		return cancelChoice
	}
	picked := ChoiceModalPickedMsg{Index: m.focused, Label: m.choices[m.focused]}
	return func() tea.Msg { return picked }
}

func cancelChoice() tea.Msg { return ChoiceModalCancelledMsg{} }

// View renders the modal.
func (m *ChoiceModal) View() string {
	var b strings.Builder

	b.WriteString(theme.TitleStyle.Render(m.title))
	b.WriteString("\n\n")
	b.WriteString(m.message)
	b.WriteString("\n\n")

	// The actions are "danger" and Cancel is "primary", the same split as
	// Yes/No: it's the safe button that carries the calm color.
	buttons := make([]string, 0, len(m.choices)+1)
	for i, choice := range m.choices {
		buttons = append(buttons, theme.RenderButton(choice, m.focused == i, "danger"))
	}
	buttons = append(buttons, theme.RenderButton("Cancel", m.focused == len(m.choices), "primary"))

	b.WriteString(strings.Join(buttons, theme.Bg("  ")))
	b.WriteString("\n\n")

	return lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorText).
		Border(lipgloss.NormalBorder()).
		BorderForeground(theme.ColorError).
		BorderBackground(theme.ColorBackground).
		Padding(1, 2).
		Render(b.String())
}

// Package keymap declares the application's keyboard vocabulary.
//
// It does not read any key and does not depend on bubbletea: it is a list of
// strings, and its only role is to be the reference the tests check the code
// against (keymap_test.go). Without this reference, key consistency is a
// convention that nothing verifies — which is exactly the state §3.26 found:
// 184 bindings, 16 collisions.
//
// # Three disjoint namespaces
//
//   - An UPPERCASE letter is an action, and its meaning is global to the
//     application. `D` deletes, in every view, whatever "delete" means
//     wherever you are.
//   - A lowercase letter is a filter or a display toggle. It changes
//     nothing, so its meaning can be local and two views can use the same
//     letter without contradicting each other.
//   - Everything else (arrows, esc, enter, tab, space, `/`, `.`, `?`, `:`) is
//     structural and never changes.
//
// # Why Shift carries the actions
//
// This isn't a matter of taste, it's the real budget of a terminal:
//
//	Ctrl+letter  : only encodes ASCII 0x40-0x5F, and the tty confiscates
//	               four of them (ctrl+i = TAB, ctrl+m = Enter, ctrl+j = LF,
//	               ctrl+h = Backspace). ctrl+a and ctrl+b are screen's and
//	               tmux's prefixes, ctrl+c/ctrl+d are SIGINT and EOF,
//	               ctrl+s/ctrl+q are flow control.           → ~14 left
//	Alt+key      : Option is not Meta on macOS unless the user enables it;
//	               the application receives nothing.                → 0
//	Ctrl+Shift   : the control code erases case — ctrl+a and ctrl+shift+a
//	               both emit 0x01. Telling them apart requires the Kitty
//	               keyboard protocol or modifyOtherKeys, which bubbletea
//	               v1.3.10 does not enable (that's WithKeyboardEnhancements()
//	               in v2). And even then the emulator claims them first:
//	               ctrl+shift+c/v/t/w/n are copy, paste, tab, close, window.
//	                                                                  → 0
//	Shift+letter : no constraint. Works on every emulator, every platform,
//	               through SSH and tmux.                             → 26
//
// Shift+letter IS a two-key combination: two fingers, no accidental firing.
// It carries the vocabulary not by default, but because the two other
// families are crippled or unusable.
package keymap

import (
	"maps"
	"sort"
	"strings"
)

// The 24 actions. About forty actions used to exist for 26 letters: the
// rule only holds after merging synonyms (Kill = stop and kill,
// Delete = delete and remove, Terminal = terminal and shell) and because
// display toggles are excluded from the count.
const (

)

// CommandMode opens the command palette, from anywhere — including from a
// focused text field.
//
// ctrl+p, and not ctrl+: : ":" is 0x3A, outside the 0x40-0x5F range Ctrl
// encodes, so "ctrl+:" never reaches the application. The fallback was
// alt+:, which has the opposite flaw: on Terminal.app and iTerm2,
// Option+Shift+; emits a literal character and the key doesn't arrive
// either. ctrl+p is free throughout the application, is not a tty control
// character, is not the prefix of any multiplexer, and its meaning is
// already learned — command palette.
const CommandMode = "ctrl+p"

// Space is the space key as KeyPressMsg.String() reports it in bubbletea v2
// ("space"). Code matches it through this name, never through a literal.
const Space = "space"

// actions maps each action key to its meaning. This is the table the tests
// check the code against; the table in §3.26 is its readable form.
var actions = map[string]string{
	New:      "Create a resource from this context",
	Edit:     "Edit the selected resource",
	Delete:   "Delete the selected resource",
	Rename:   "Rename",
	Scan:     "Scan the selected target",
	ScanAll:  "Scan everything",
	Fetch:    "Catch up with the source",
	Clone:    "Enter clone selection",
	Terminal: "Open a terminal or shell",
	IDE:      "Open in the configured IDE",
	Web:      "Open a URL in the browser",
	Logs:     "Open the logs",
	Pager:    "Open in the system pager",
	Kill:     "Stop or kill",
	Prune:    "Remove unused resources",
	Browser:  "Open the multi-registry browser",
	Get:      "Pull the image or tag",
	Auth:     "Log in or out of the registry",
	Exclude:  "Exclude — add to .gitleaksignore",
	Requests: "Open merge requests · PRs",
	Issues:   "Open issues",
	Diagnose: "Open network diagnostics on this target",
	Jump:     "Jump to the related resource in its own view",
	Copy:     "Copy the obvious thing to the clipboard",
}

// Actions returns a copy of the key → meaning table.
func Actions() map[string]string {
	out := make(map[string]string, len(actions))
	maps.Copy(out, actions)
	return out
}

// IsAction reports whether a key belongs to the action vocabulary.
func IsAction(key string) bool {
	_, ok := actions[key]
	return ok
}

// modalKeys are the shortcuts of a confirmation modal.
//
// This is a fourth namespace, and it is disjoint from the other three by
// mode rather than by case: a modal claims every key before the view sees
// it (priority 1 in every handleKeyMsg), so `N` cannot mean "create" there
// — the view underneath receives nothing. Same argument as for InEditMode.
//
// They are declared here because the §3.26 survey had not seen them, and
// an uppercase letter bound without a declaration is indistinguishable
// from drift.
var modalKeys = map[string]string{
	"y": "Yes", "Y": "Yes",
	"n": "No", "N": "No",
}

// ModalKeys returns the modal shortcuts.
func ModalKeys() map[string]string {
	out := make(map[string]string, len(modalKeys))
	maps.Copy(out, modalKeys)
	return out
}

// IsModalKey reports whether a key is a modal shortcut.
func IsModalKey(key string) bool {
	_, ok := modalKeys[key]
	return ok
}

// free lists the uppercase letters no action occupies. They are declared
// rather than left to be inferred: the next addition must know where to
// pick from without redoing the survey, and an action that settles
// somewhere other than here is a duplicate that goes unnoticed.
// H came back here with §3.47 (it used to trace the route, removed because
// it answered for the Docker VM rather than for the machine, D57) and left
// again with Diagnose (§3.66): a good semantic fit for "look closer at this
// target's network path." A letter an action has just freed up is
// re-declared free, otherwise it stays reserved for a use that no longer
// exists. J left with Jump (a container's image, opened in the OCI view).
var free = []string{"Q", "Z"}

// Free returns the still-available uppercase letters, sorted.
func Free() []string {
	out := append([]string(nil), free...)
	sort.Strings(out)
	return out
}

// Surface is a screen, its files, and the lowercase letters it uses.
//
// Path is what ties a file to its surface, and it is there so the
// declaration is checkable: without it, "these letters are local to this
// view" is verified by merging every list, and `l` declared for netdiag
// would excuse `l` in the registries. Matching is done on the longest
// prefix, so netdiag/ports can narrow down netdiag.
type Surface struct {
	Name string
	Path string
	Keys []string
}

// localToggles inventories the lowercase letters used as display or filter
// toggles. They change nothing, so their meaning is local and the same
// letter can serve twice without contradiction — `l` is the protocol in
// netdiag and the LOW severity in security.
//
// A file that matches no surface is entitled to no lowercase letter at
// all: that is the default, and it is what makes the list worth keeping
// up to date.
var localToggles = []Surface{
	{"containers", "ui/containers/", []string{"r", "p", "s", "t", "z"}},
	{"viewer", "ui/viewer/", []string{"f", "c", "w", "v", "t", "n", "g", "s"}},
	{"netdiag/ports", "ui/netdiag/ports_model.go", []string{"t", "u", "l", "e", "n", "z"}},
	{"netdiag/checks", "ui/netdiag/", []string{"p"}},
	{"oci/browser", "ui/oci_resources/browser_", []string{"r"}},
	{"security/findings", "ui/security/", []string{"c", "h", "m", "l"}},
	// g opens the fuzzy-find prompt across the whole workspaces tree. Same
	// justification as the viewer's g: the jump takes an argument (the typed
	// query), which is not a role home/end/G could ever cover.
	{"workspaces", "ui/workspaces/", []string{"g"}},
	// The same prompt over the forge index: every namespace and repository
	// the session can see, at any depth.
	{"forge/explorer", "ui/forge/explorer/", []string{"g"}},
}

// LocalToggles returns the declared surfaces.
func LocalToggles() []Surface {
	return append([]Surface(nil), localToggles...)
}

// SurfaceFor ties a file path to its surface, by longest prefix. The
// second return says whether a surface was found.
func SurfaceFor(path string) (Surface, bool) {
	var best Surface
	found := false
	for _, s := range localToggles {
		if !strings.Contains(path, s.Path) {
			continue
		}
		if !found || len(s.Path) > len(best.Path) {
			best, found = s, true
		}
	}
	return best, found
}

// Exception is a key that deviates from the vocabulary, with its reason.
type Exception struct {
	Key     string
	Surface string
	Why     string
}

// exceptions are the accepted deviations. They are written here
// because §3.26 requires it: an undeclared exception is indistinguishable
// from drift, and the next survey would "fix" it.
var exceptions = []Exception{
	{
		Key:     "o",
		Surface: "security/results/ci-tab",
		Why: "Ouvrir le pipeline résolu par le forge. Même raison que `c` : " +
			"l'action n'existe que sur un onglet, et brûler une des trois " +
